-- rowstile 0.1.0-dev: a_column_wins. Generated by rowstile migrate from the policy; don't edit it,
-- change the policy and write the next migration.
-- the same policy; what rowstile makes of it changed

-- a migration is one transaction: outside one, nothing below changes anything
SELECT pg_catalog.set_config('authz_ctx.migration', '1553b7bad422aa08', true);
DO $authz_tx$
BEGIN
  IF pg_catalog.current_setting('authz_ctx.migration', true) IS DISTINCT FROM '1553b7bad422aa08' THEN
    PERFORM pg_catalog.set_config('authz_migration.read_only', pg_catalog.current_setting('default_transaction_read_only'), false);
    PERFORM pg_catalog.set_config('default_transaction_read_only', 'on', false);
  END IF;
END $authz_tx$;
DO $authz_tx$
BEGIN
  IF pg_catalog.current_setting('authz_ctx.migration', true) IS DISTINCT FROM '1553b7bad422aa08' THEN
    RAISE EXCEPTION 'rowstile: this migration must run in one transaction, and its statements are being committed one by one [AZ615]'
      USING HINT = 'nothing was changed, and this session is read-only until the migration''s last statement; run the file with your migration tool, or with psql -1 -f';
  END IF;
END $authz_tx$;

SELECT pg_catalog.set_config('lock_timeout', '10s', true) WHERE pg_catalog.current_setting('lock_timeout') IN ('0', '0ms');
SELECT pg_catalog.set_config('check_function_bodies', 'off', true);

-- this migration starts from the policy the previous one left
DO $authz_guard$
DECLARE v_lock text;
BEGIN
  IF to_regclass('authz.policy_versions') IS NOT NULL THEN
    EXECUTE 'SELECT lock FROM authz.policy_versions ORDER BY id DESC LIMIT 1' INTO v_lock;
  END IF;
  IF v_lock = '1553b7bad422aa08' THEN
    RAISE EXCEPTION 'rowstile: this database already holds what this migration brings (it ran here before, or rowstile dev or push took the database there): don''t run it, tell your migration tool it is applied [AZ607]'
      USING HINT = 'Prisma: prisma migrate resolve --applied <the migration''s folder>. Alembic: alembic stamp head. '
                   'Others, and why: rowstile help AZ607';
  ELSIF v_lock IS DISTINCT FROM 'e525b5e59e8010dc' THEN
    RAISE EXCEPTION 'rowstile: this migration changes the policy the migration before it left (%), but the database has % [AZ607]',
      'e525b5e59e8010dc', coalesce(v_lock, 'none')
      USING HINT = 'apply the migrations in order; a database changed with rowstile push or apply since needs the '
                   'migrations from the start (or rowstile apply of the policy the previous migration left) '
                   '(rowstile help AZ607)';
  END IF;
END $authz_guard$;

-- The app role must not be the policy's owner, nor a member of it: the rules would not hold for it
DO $ar$
DECLARE v_app name;
BEGIN
  SELECT a.rolname INTO v_app FROM pg_catalog.pg_roles a
  WHERE a.rolname = 'ms_app' AND NOT a.rolsuper AND pg_catalog.pg_has_role(a.oid, CURRENT_USER, 'MEMBER');
  IF v_app IS NOT NULL THEN
    RAISE EXCEPTION 'the app role % is the role that applies the policy (%), or a member of it: the rules would not hold for it [AZ624]', v_app, CURRENT_USER
      USING HINT = 'the policy''s owner skips row-level security, may turn it off, and is believed without a signature: the app connects as a role of its own, which owns nothing of the database';
  END IF;
END $ar$;

-- Functions below resolve names with the search_path in effect now: the schemas that exist, temporary schema last
DO $sp$
DECLARE v_path text; v_bad text; f record;
BEGIN
  SELECT pg_catalog.string_agg(pg_catalog.format('%I (%s)', pw.schema, pw.who), ', ') INTO v_bad FROM (SELECT n.nspname::text AS schema, w.who
FROM pg_catalog.unnest(pg_catalog.current_schemas(false)) s(name) JOIN pg_catalog.pg_namespace n ON n.nspname = s.name,
LATERAL (SELECT CASE WHEN EXISTS (SELECT 1 FROM pg_catalog.aclexplode(n.nspacl) a
                                  WHERE a.grantee = 0 AND a.privilege_type = 'CREATE') THEN 'PUBLIC'
                ELSE (SELECT pg_catalog.string_agg(ro.rolname::text, ', ' ORDER BY ro.rolname) FROM pg_catalog.pg_roles ro
                      WHERE pg_catalog.has_schema_privilege(ro.oid, n.oid, 'CREATE') AND NOT ro.rolsuper
                        AND ro.rolname <> 'pg_database_owner' AND NOT pg_catalog.pg_has_role(ro.oid, CURRENT_USER, 'MEMBER')
                        AND NOT pg_catalog.pg_has_role(ro.oid, (SELECT d.datdba FROM pg_catalog.pg_database d
                                                               WHERE d.datname = pg_catalog.current_database()), 'MEMBER'))
                END AS who) w
-- a temporary schema is the session's own, and never searched for functions or operators
WHERE w.who IS NOT NULL AND n.nspname !~ '^pg_(toast_)?temp_') pw;
  IF v_bad IS NOT NULL THEN
    RAISE EXCEPTION 'the search path has schemas that roles other than the owner may create objects in: % [AZ612]', v_bad
      USING HINT = 'rowstile''s functions that run as the owner resolve names on this path, so a function made there could run as the owner: revoke CREATE on those schemas, or apply with a search path without them';
  END IF;
  SELECT pg_catalog.string_agg(pg_catalog.quote_ident(s.name), ', ' ORDER BY s.i) INTO v_path
  FROM pg_catalog.unnest(pg_catalog.current_schemas(false)) WITH ORDINALITY s(name, i)
  WHERE s.name::text !~ '^pg_temp_';
  PERFORM pg_catalog.set_config('search_path', pg_catalog.concat_ws(', ', v_path, 'pg_temp'), true);
  -- functions made before (a migration keeps those it doesn't change) take the same path
  FOR f IN SELECT p.oid::regprocedure AS fn FROM pg_catalog.pg_proc p
           WHERE p.pronamespace IN (SELECT n.oid FROM pg_catalog.pg_namespace n WHERE n.nspname IN ('authz', 'authz_gen', 'authz_int'))
             AND EXISTS (SELECT 1 FROM pg_catalog.unnest(p.proconfig) c
                         WHERE c ^@ 'search_path=' AND c <> 'search_path=pg_catalog, pg_temp'
                           AND c <> 'search_path=' || pg_catalog.current_setting('search_path')) LOOP
    EXECUTE pg_catalog.format('ALTER FUNCTION %s SET search_path FROM CURRENT', f.fn);
  END LOOP;
END $sp$;

CREATE OR REPLACE FUNCTION authz.uid() RETURNS uuid LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path FROM CURRENT AS $uid$
#variable_conflict use_column
BEGIN RETURN (SELECT u."id" FROM "ms"."users" u WHERE u."id" = (CASE WHEN authz_int.session_ok() AND coalesce(pg_catalog.current_setting('authz.principal_type', true), '') IN ('', 'user') AND pg_catalog.pg_input_is_valid(pg_catalog.current_setting('authz.user_id', true), 'uuid') THEN pg_catalog.current_setting('authz.user_id', true)::uuid END)); END
$uid$;

-- the signed-in bot, if one is signed in (an id its table doesn't have, or one failing the type's where, counts as nobody)
CREATE OR REPLACE FUNCTION authz_int."bot__me"() RETURNS bigint LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path FROM CURRENT AS $me$
#variable_conflict use_column
BEGIN RETURN (SELECT w."id" FROM "ms"."bots" w WHERE w."id" = (CASE WHEN authz_int.session_ok() AND pg_catalog.current_setting('authz.principal_type', true) = 'bot' AND pg_catalog.pg_input_is_valid(pg_catalog.current_setting('authz.user_id', true), 'bigint') THEN pg_catalog.current_setting('authz.user_id', true)::bigint END) AND coalesce((active), false)); END
$me$;
-- what it reads, read now (Postgres reads a PL/pgSQL function's queries when they first run)
DO $read$
#variable_conflict use_column
BEGIN
  PERFORM 1 FROM "ms"."bots" w WHERE coalesce((active), false) LIMIT 0;
END $read$;

-- What else may have changed when objects of a type did: the objects that read them through a relation (a
-- dot, inheritance, a group's members, a group inside a group), then those that read those, until nothing
-- is new. Past 1000 objects of a type: all of them ({*}), and all of what reads them. Each is
-- announced with the cause 'dependent'.
CREATE OR REPLACE FUNCTION authz_int.dependents(p_type text, p_ids text[]) RETURNS void
LANGUAGE plpgsql SECURITY DEFINER SET search_path = pg_catalog, pg_temp AS $f$
#variable_conflict use_column
<<authz__>>
DECLARE
  v_all boolean := '*' = ANY (p_ids);
  v_rows bigint; v_most int;
  -- for each type: the ids known (s), new in the last round (n), found in this one (x), how many were found (c),
  -- and whether it is all of them (a)
  s1 bigint[] := '{}'; n1 bigint[] := '{}'; x1 bigint[]; c1 int := 0; a1 boolean := false;  -- bot
  s2 bigint[] := '{}'; n2 bigint[] := '{}'; x2 bigint[]; c2 int := 0; a2 boolean := false;  -- chat
  s3 text[] := '{}'; n3 text[] := '{}'; x3 text[]; c3 int := 0; a3 boolean := false;  -- chat_bot
  s4 text[] := '{}'; n4 text[] := '{}'; x4 text[]; c4 int := 0; a4 boolean := false;  -- membership
  s5 text[] := '{}'; n5 text[] := '{}'; x5 text[]; c5 int := 0; a5 boolean := false;  -- message
  s6 uuid[] := '{}'; n6 uuid[] := '{}'; x6 uuid[]; c6 int := 0; a6 boolean := false;  -- user
BEGIN
  CASE p_type
    WHEN 'bot' THEN
      IF v_all THEN a1 := true;
      ELSE n1 := ARRAY(SELECT DISTINCT x::bigint FROM unnest(p_ids) x WHERE pg_input_is_valid(x, 'bigint')); s1 := n1;
      END IF;
    WHEN 'chat' THEN
      IF v_all THEN a2 := true;
      ELSE n2 := ARRAY(SELECT DISTINCT x::bigint FROM unnest(p_ids) x WHERE pg_input_is_valid(x, 'bigint')); s2 := n2;
      END IF;
    WHEN 'user' THEN
      IF v_all THEN a6 := true;
      ELSE n6 := ARRAY(SELECT DISTINCT x::uuid FROM unnest(p_ids) x WHERE pg_input_is_valid(x, 'uuid')); s6 := n6;
      END IF;
    ELSE RETURN;  -- nothing reads its objects
  END CASE;
  LOOP
    -- all of a type: all of what reads it too
    IF a1 THEN a3 := true; END IF;
    IF a2 THEN a3 := true; a4 := true; a5 := true; a6 := true; END IF;
    IF a6 THEN a4 := true; END IF;
    EXIT WHEN (a1 OR cardinality(n1) = 0) AND (a2 OR cardinality(n2) = 0) AND (a3 OR cardinality(n3) = 0) AND (a4 OR cardinality(n4) = 0) AND (a5 OR cardinality(n5) = 0) AND (a6 OR cardinality(n6) = 0);
    IF NOT a3 AND (cardinality(n1) > 0 OR cardinality(n2) > 0) THEN
      v_most := cardinality(s3) + 1001;
      SELECT count(*), coalesce(array_agg(DISTINCT d.v) FILTER (WHERE d.v IS NOT NULL AND NOT d.v = ANY (authz__.s3)), '{}')
        INTO v_rows, x3
        FROM (SELECT ROW(x."chat_id"::bigint, x."bot_id"::bigint)::text FROM "ms"."chat_bots" x WHERE x."bot_id" = ANY (authz__.n1) AND cardinality(authz__.n1) > 0
          UNION ALL SELECT ROW(x."chat_id"::bigint, x."bot_id"::bigint)::text FROM "ms"."chat_bots" x WHERE x."chat_id" = ANY (authz__.n2) AND cardinality(authz__.n2) > 0
          LIMIT authz__.v_most) d(v);
      a3 := v_rows >= v_most;
    ELSE
      x3 := '{}';
    END IF;
    IF NOT a4 AND (cardinality(n2) > 0 OR cardinality(n6) > 0) THEN
      v_most := cardinality(s4) + 1001;
      SELECT count(*), coalesce(array_agg(DISTINCT d.v) FILTER (WHERE d.v IS NOT NULL AND NOT d.v = ANY (authz__.s4)), '{}')
        INTO v_rows, x4
        FROM (SELECT ROW(x."chat_id"::bigint, x."user_id"::uuid)::text FROM "ms"."members" x WHERE x."chat_id" = ANY (authz__.n2) AND cardinality(authz__.n2) > 0
          UNION ALL SELECT ROW(x."chat_id"::bigint, x."user_id"::uuid)::text FROM "ms"."members" x WHERE x."user_id" = ANY (authz__.n6) AND cardinality(authz__.n6) > 0
          LIMIT authz__.v_most) d(v);
      a4 := v_rows >= v_most;
    ELSE
      x4 := '{}';
    END IF;
    IF NOT a5 AND (cardinality(n2) > 0) THEN
      v_most := cardinality(s5) + 1001;
      SELECT count(*), coalesce(array_agg(DISTINCT d.v) FILTER (WHERE d.v IS NOT NULL AND NOT d.v = ANY (authz__.s5)), '{}')
        INTO v_rows, x5
        FROM (SELECT ROW(x."chat_id"::bigint, x."seq"::bigint)::text FROM "ms"."messages" x WHERE x."chat_id" = ANY (authz__.n2) AND cardinality(authz__.n2) > 0
          LIMIT authz__.v_most) d(v);
      a5 := v_rows >= v_most;
    ELSE
      x5 := '{}';
    END IF;
    IF NOT a6 AND (cardinality(n2) > 0) THEN
      v_most := cardinality(s6) + 1001;
      SELECT count(*), coalesce(array_agg(DISTINCT d.v) FILTER (WHERE d.v IS NOT NULL AND NOT d.v = ANY (authz__.s6)), '{}')
        INTO v_rows, x6
        FROM (SELECT x."user_id" FROM "ms"."members" x WHERE x."chat_id" = ANY (authz__.n2) AND cardinality(authz__.n2) > 0
          LIMIT authz__.v_most) d(v);
      a6 := v_rows >= v_most;
    ELSE
      x6 := '{}';
    END IF;
    n1 := '{}';
    n2 := '{}';
    n3 := x3; s3 := s3 || x3; c3 := c3 + cardinality(x3); a3 := a3 OR c3 > 1000;
    n4 := x4; s4 := s4 || x4; c4 := c4 + cardinality(x4); a4 := a4 OR c4 > 1000;
    n5 := x5; s5 := s5 || x5; c5 := c5 + cardinality(x5); a5 := a5 OR c5 > 1000;
    n6 := x6; s6 := s6 || x6; c6 := c6 + cardinality(x6); a6 := a6 OR c6 > 1000;
  END LOOP;
  IF a3 AND NOT (v_all AND p_type = 'chat_bot') THEN
    PERFORM authz_int.announce('chat_bot', '{*}', 'dependent', false);
  ELSIF NOT a3 AND c3 > 0 THEN
    PERFORM authz_int.announce('chat_bot', ARRAY(SELECT v::text FROM unnest(s3[cardinality(s3) - c3 + 1:]) v ORDER BY v), 'dependent', false);
  END IF;
  IF a4 AND NOT (v_all AND p_type = 'membership') THEN
    PERFORM authz_int.announce('membership', '{*}', 'dependent', false);
  ELSIF NOT a4 AND c4 > 0 THEN
    PERFORM authz_int.announce('membership', ARRAY(SELECT v::text FROM unnest(s4[cardinality(s4) - c4 + 1:]) v ORDER BY v), 'dependent', false);
  END IF;
  IF a5 AND NOT (v_all AND p_type = 'message') THEN
    PERFORM authz_int.announce('message', '{*}', 'dependent', false);
  ELSIF NOT a5 AND c5 > 0 THEN
    PERFORM authz_int.announce('message', ARRAY(SELECT v::text FROM unnest(s5[cardinality(s5) - c5 + 1:]) v ORDER BY v), 'dependent', false);
  END IF;
  IF a6 AND NOT (v_all AND p_type = 'user') THEN
    PERFORM authz_int.announce('user', '{*}', 'dependent', false);
  ELSIF NOT a6 AND c6 > 0 THEN
    PERFORM authz_int.announce('user', ARRAY(SELECT v::text FROM unnest(s6[cardinality(s6) - c6 + 1:]) v ORDER BY v), 'dependent', false);
  END IF;
END $f$;

-- a role that gives more or less: the objects it is given on (its assignments are shares, 'role:<id>'; a change:
-- the roles it was in and is in)
CREATE OR REPLACE FUNCTION authz_int.on_role_permissions() RETURNS trigger
LANGUAGE plpgsql SECURITY DEFINER SET search_path = pg_catalog, pg_temp AS $f$
#variable_conflict use_column
BEGIN
  IF TG_OP = 'UPDATE' THEN
    PERFORM authz_int.changed(g.object_type, array_agg(DISTINCT g.object_id), 'role')
    FROM authz.shares g WHERE g.relation IN (SELECT 'role:' || r.role_id FROM role_rows r
                                             UNION SELECT 'role:' || n.role_id FROM new_role_rows n) GROUP BY g.object_type;
  ELSE
    PERFORM authz_int.changed(g.object_type, array_agg(DISTINCT g.object_id), 'role')
    FROM authz.shares g WHERE g.relation IN (SELECT 'role:' || r.role_id FROM role_rows r) GROUP BY g.object_type;
  END IF;
  RETURN NULL;
END $f$;

-- 'shared if {...}' conditions (they run as the policy's owner, like permissions). A bare name in one is
-- a column of what the condition reads, never a parameter of this function
CREATE OR REPLACE FUNCTION authz_int.share_if(p_key text, p_object_id text, p_subject_type text, p_subject_id text,
  p_subject_relation text) RETURNS boolean
LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path FROM CURRENT AS $f$
#variable_conflict use_column
BEGIN
  CASE p_key
    WHEN NULL THEN NULL;
    ELSE RETURN true;
  END CASE;
END $f$;

-- deleting a role removes its assignments
CREATE OR REPLACE FUNCTION authz_int.role_gone() RETURNS trigger
LANGUAGE plpgsql SECURITY DEFINER SET search_path = pg_catalog, pg_temp AS $f$
#variable_conflict use_column
BEGIN
  DELETE FROM authz.shares WHERE relation IN (SELECT 'role:' || o.id FROM old_rows o);
  RETURN NULL;
END $f$;

-- shares on chat rows that are gone, or whose id changed, are removed (and their marks: forget_marks), and
-- the pending requests naming them are cancelled (requests_gone)
CREATE OR REPLACE FUNCTION authz_int."chat__forget"() RETURNS trigger
LANGUAGE plpgsql SECURITY DEFINER SET search_path FROM CURRENT AS $f$
#variable_conflict use_column
DECLARE v_gone text[];
BEGIN
  IF TG_OP = 'TRUNCATE' THEN
    IF NOT EXISTS (SELECT 1 FROM "ms"."chats") THEN   -- the table is empty, and so are those under it
      DELETE FROM authz.shares WHERE object_type = 'chat';
      DELETE FROM authz.shares WHERE subject_type = 'chat' AND subject_id <> '*';      -- '*' (every one signed in) names no row
      DELETE FROM authz_int.row_marks WHERE type = 'chat';
      PERFORM authz_int.requests_gone('chat', NULL);
    ELSE   -- TRUNCATE ONLY, or of a table under it: some rows are still there. What named a row that is gone goes
      -- (the pending requests naming one were cancelled before, while it was there to tell)
      v_gone := ARRAY(SELECT g.id FROM (SELECT s.object_id FROM authz.shares s WHERE s.object_type = 'chat'
                                        UNION SELECT s.subject_id FROM authz.shares s WHERE s.subject_type = 'chat' AND s.subject_id <> '*'
                                        UNION SELECT m.id FROM authz_int.row_marks m WHERE m.type = 'chat') g(id)
                      WHERE NOT EXISTS (SELECT 1 FROM "ms"."chats" x WHERE x."id"::text = g.id));
      PERFORM authz_int.forget_marks('chat', v_gone);
      DELETE FROM authz.shares WHERE object_type = 'chat' AND object_id = ANY (v_gone);
      DELETE FROM authz.shares WHERE subject_type = 'chat' AND subject_id = ANY (v_gone);
    END IF;
  ELSIF TG_OP = 'UPDATE' THEN   -- on a partitioned table (the last trigger below): the ids the update left no row with
    PERFORM authz_int.forget_marks('chat', ARRAY(SELECT o."id"::text FROM old_rows o EXCEPT SELECT n."id"::text FROM new_rows n));
    DELETE FROM authz.shares WHERE object_type = 'chat' AND object_id IN (SELECT o."id"::text FROM old_rows o EXCEPT SELECT n."id"::text FROM new_rows n);
    DELETE FROM authz.shares WHERE subject_type = 'chat' AND subject_id IN (SELECT o."id"::text FROM old_rows o EXCEPT SELECT n."id"::text FROM new_rows n);
    PERFORM authz_int.requests_gone('chat', ARRAY(SELECT o."id"::text FROM old_rows o EXCEPT SELECT n."id"::text FROM new_rows n));
  ELSE
    PERFORM authz_int.forget_marks('chat', ARRAY(SELECT o."id"::text FROM old_rows o));
    DELETE FROM authz.shares WHERE object_type = 'chat' AND object_id IN (SELECT o."id"::text FROM old_rows o);
    DELETE FROM authz.shares WHERE subject_type = 'chat' AND subject_id IN (SELECT o."id"::text FROM old_rows o);
    PERFORM authz_int.requests_gone('chat', ARRAY(SELECT o."id"::text FROM old_rows o));
  END IF;
  RETURN NULL;
END $f$;

-- relationships kept in ms.blocks
CREATE OR REPLACE FUNCTION authz_int."rel_audit_1_ins"() RETURNS trigger
LANGUAGE plpgsql SECURITY DEFINER SET search_path FROM CURRENT AS $f$
#variable_conflict use_column
BEGIN
    INSERT INTO authz.audit (db_role, user_id, acting_user, action, object_type, object_id, relation, subject_type,
                             subject_id, subject_relation, reason)
    SELECT authz_int.caller_role(), authz_int.actor(),
           nullif(current_setting('authz.acting_user', true), ''), c.action, c.ot, c.oid, c.rel, c.st, c.sid, c.sr,
           nullif(current_setting('authz_ctx.reason', true), '')
    FROM (SELECT 'relate' AS action, 'user' AS ot, x."blocker_id"::text AS oid, 'has_blocked' AS rel, 'user' AS st, x."blocked_id"::text AS sid, '' AS sr FROM new_rows x WHERE true) c;
    PERFORM authz_int.changed(c.ot, array_agg(DISTINCT c.oid), 'relationship') FROM (SELECT 'relate' AS action, 'user' AS ot, x."blocker_id"::text AS oid, 'has_blocked' AS rel, 'user' AS st, x."blocked_id"::text AS sid, '' AS sr FROM new_rows x WHERE true) c GROUP BY c.ot;
  RETURN NULL;
END $f$;

CREATE OR REPLACE FUNCTION authz_int."rel_audit_1_upd"() RETURNS trigger
LANGUAGE plpgsql SECURITY DEFINER SET search_path FROM CURRENT AS $f$
#variable_conflict use_column
BEGIN
    INSERT INTO authz.audit (db_role, user_id, acting_user, action, object_type, object_id, relation, subject_type,
                             subject_id, subject_relation, reason)
    SELECT authz_int.caller_role(), authz_int.actor(),
           nullif(current_setting('authz.acting_user', true), ''), c.action, c.ot, c.oid, c.rel, c.st, c.sid, c.sr,
           nullif(current_setting('authz_ctx.reason', true), '')
    FROM (SELECT 'relate' AS action, 'user' AS ot, x."blocker_id"::text AS oid, 'has_blocked' AS rel, 'user' AS st, x."blocked_id"::text AS sid, '' AS sr FROM new_rows x WHERE true) c
    WHERE NOT EXISTS (SELECT 1 FROM (SELECT 'unrelate' AS action, 'user' AS ot, x."blocker_id"::text AS oid, 'has_blocked' AS rel, 'user' AS st, x."blocked_id"::text AS sid, '' AS sr FROM old_rows x WHERE true) o WHERE (o.ot, o.oid, o.rel, o.st, o.sid) = (c.ot, c.oid, c.rel, c.st, c.sid));
    PERFORM authz_int.changed(c.ot, array_agg(DISTINCT c.oid), 'relationship') FROM (SELECT 'relate' AS action, 'user' AS ot, x."blocker_id"::text AS oid, 'has_blocked' AS rel, 'user' AS st, x."blocked_id"::text AS sid, '' AS sr FROM new_rows x WHERE true) c GROUP BY c.ot;
    INSERT INTO authz.audit (db_role, user_id, acting_user, action, object_type, object_id, relation, subject_type,
                             subject_id, subject_relation, reason)
    SELECT authz_int.caller_role(), authz_int.actor(),
           nullif(current_setting('authz.acting_user', true), ''), c.action, c.ot, c.oid, c.rel, c.st, c.sid, c.sr,
           nullif(current_setting('authz_ctx.reason', true), '')
    FROM (SELECT 'unrelate' AS action, 'user' AS ot, x."blocker_id"::text AS oid, 'has_blocked' AS rel, 'user' AS st, x."blocked_id"::text AS sid, '' AS sr FROM old_rows x WHERE true) c
    WHERE NOT EXISTS (SELECT 1 FROM (SELECT 'relate' AS action, 'user' AS ot, x."blocker_id"::text AS oid, 'has_blocked' AS rel, 'user' AS st, x."blocked_id"::text AS sid, '' AS sr FROM new_rows x WHERE true) o WHERE (o.ot, o.oid, o.rel, o.st, o.sid) = (c.ot, c.oid, c.rel, c.st, c.sid));
    PERFORM authz_int.changed(c.ot, array_agg(DISTINCT c.oid), 'relationship') FROM (SELECT 'unrelate' AS action, 'user' AS ot, x."blocker_id"::text AS oid, 'has_blocked' AS rel, 'user' AS st, x."blocked_id"::text AS sid, '' AS sr FROM old_rows x WHERE true) c GROUP BY c.ot;
  RETURN NULL;
END $f$;

CREATE OR REPLACE FUNCTION authz_int."rel_audit_1_del"() RETURNS trigger
LANGUAGE plpgsql SECURITY DEFINER SET search_path FROM CURRENT AS $f$
#variable_conflict use_column
BEGIN
    INSERT INTO authz.audit (db_role, user_id, acting_user, action, object_type, object_id, relation, subject_type,
                             subject_id, subject_relation, reason)
    SELECT authz_int.caller_role(), authz_int.actor(),
           nullif(current_setting('authz.acting_user', true), ''), c.action, c.ot, c.oid, c.rel, c.st, c.sid, c.sr,
           nullif(current_setting('authz_ctx.reason', true), '')
    FROM (SELECT 'unrelate' AS action, 'user' AS ot, x."blocker_id"::text AS oid, 'has_blocked' AS rel, 'user' AS st, x."blocked_id"::text AS sid, '' AS sr FROM old_rows x WHERE true) c;
