        UNION SELECT ROW(o."blocker_id"::uuid, o."blocked_id"::uuid)::text FROM old_rows o WHERE NOT EXISTS (SELECT 1 FROM new_rows n WHERE ROW(n."blocker_id"::uuid, n."blocked_id"::uuid)::text = ROW(o."blocker_id"::uuid, o."blocked_id"::uuid)::text)
        UNION SELECT ROW(n."blocker_id"::uuid, n."blocked_id"::uuid)::text FROM new_rows n JOIN old_rows o ON ROW(n."blocker_id"::uuid, n."blocked_id"::uuid)::text = ROW(o."blocker_id"::uuid, o."blocked_id"::uuid)::text
        WHERE n."blocker_id" IS DISTINCT FROM o."blocker_id"), 'update');
    -- a partitioned table: the rows this update put in another partition, which the row trigger never sees
    IF (SELECT relkind FROM pg_class WHERE oid = TG_RELID) = 'p' THEN
      INSERT INTO authz.audit (db_role, user_id, acting_user, action, object_type, object_id, relation, subject_id, detail, reason)
      SELECT authz_int.caller_role(), authz_int.actor(), nullif(current_setting('authz.acting_user', true), ''), 'relate', 'block', ROW(n."blocker_id"::uuid, n."blocked_id"::uuid)::text, 'blocker', n."blocker_id"::text, jsonb_build_object('column', 'blocker_id', 'was', o."blocker_id"), nullif(current_setting('authz_ctx.reason', true), '')
