      WHERE n."blocker_id" IS DISTINCT FROM o."blocker_id" AND NOT EXISTS (
        SELECT 1 FROM authz.audit a WHERE a.txid = txid_current() AND a.action = 'relate' AND a.object_type = 'block'
          AND a.object_id = ROW(n."blocker_id"::uuid, n."blocked_id"::uuid)::text AND a.relation = 'blocker' AND a.detail->>'column' = 'blocker_id'
          AND a.subject_id IS NOT DISTINCT FROM n."blocker_id"::text AND a.detail->'was' IS NOT DISTINCT FROM to_jsonb(o."blocker_id"));
    END IF;
  RETURN NULL;
END $f$;

