#variable_conflict use_column
BEGIN
  RETURN NOT EXISTS (SELECT 1 FROM "ms"."chat_bots" o WHERE (o."chat_id", o."bot_id") = ((($1)::authz_gen."chat_bot__key")."chat_id", (($1)::authz_gen."chat_bot__key")."bot_id"))
      OR EXISTS (SELECT 1 FROM "ms"."chat_bots" "chat_bots" WHERE ("chat_bots"."chat_id", "chat_bots"."bot_id") = ((($1)::authz_gen."chat_bot__key")."chat_id", (($1)::authz_gen."chat_bot__key")."bot_id")
        AND (SELECT authz_int.scope_cmd('ms.chat_bots', 'select')) AND EXISTS (SELECT 1 FROM authz_int."chat__read" v WHERE v.id = "chat_bots"."chat_id"));
END $f$;

CREATE OR REPLACE FUNCTION authz_gen."ms.chat_bots:rules:explain"(p_command text, p_id text, p_row jsonb) RETURNS text[]
LANGUAGE plpgsql STABLE SET search_path FROM CURRENT AS $f$
#variable_conflict use_column
DECLARE r_old "ms"."chat_bots"; r_new "ms"."chat_bots";
BEGIN
  IF p_command = 'insert' THEN
    RETURN ARRAY(SELECT * FROM authz_gen."ms.chat_bots:insert:why"(jsonb_populate_record(NULL::"ms"."chat_bots", coalesce($3, '{}'))));
  END IF;
  IF p_id IS NULL THEN
    RAISE EXCEPTION 'which row? authz.explain_rule(%, %, id)', 'ms.chat_bots', p_command USING ERRCODE = 'invalid_parameter_value', HINT = 'rowstile help AZ710';
  END IF;
  SELECT x.* INTO r_old FROM "ms"."chat_bots" x WHERE (x."chat_id", x."bot_id") = ((($2)::authz_gen."chat_bot__key")."chat_id", (($2)::authz_gen."chat_bot__key")."bot_id");
  IF NOT FOUND THEN
    RETURN NULL;          -- not there, or the signed-in user can't see it
  END IF;
  IF p_command = 'delete' THEN
    RETURN ARRAY(SELECT * FROM authz_gen."ms.chat_bots:delete:why"(r_old));
  END IF;
  r_new := jsonb_populate_record(r_old, coalesce(p_row, '{}'));
  RETURN ARRAY['no   there is no update rule for ms.chat_bots: nobody may update its rows'];
END $f$;

