CREATE OR REPLACE FUNCTION authz_gen."ms.blocks:insert:why"(p_row "ms"."blocks") RETURNS SETOF text
LANGUAGE plpgsql STABLE SET search_path FROM CURRENT AS $f$
DECLARE v boolean[] := authz_gen."ms.blocks:insert:items"(p_row, current_user); v_t record;
BEGIN
