        WHEN 'add_members' THEN RETURN EXISTS (SELECT 1 FROM "ms"."chats" o WHERE o."id" = authz__.v_bigint AND (((coalesce((kind = 'group'), false)
    AND EXISTS (SELECT 1 FROM authz_int."chat__admin" v WHERE v.id = o."id"))
