      v_text := p_id::authz_gen."membership__key"::text;
      RAISE EXCEPTION 'no permission %.% in the policy', p_type, p_perm USING HINT = 'rowstile help AZ707';
    WHEN 'message' THEN
      IF NOT pg_catalog.pg_input_is_valid(p_id, 'authz_gen."message__key"') THEN RETURN false; END IF;
      v_text := p_id::authz_gen."message__key"::text;
      CASE p_perm
        WHEN 'read' THEN RETURN EXISTS (SELECT 1 FROM "ms"."messages" o WHERE (o."chat_id", o."seq") = (((authz__.v_text)::authz_gen."message__key")."chat_id", ((authz__.v_text)::authz_gen."message__key")."seq") AND ((authz_int."message__check_522cac4d84"((o.*)::"ms"."messages")
    AND EXISTS (SELECT 1 FROM authz_int."chat__read" v WHERE v.id = o."chat_id"))));
        WHEN 'edit' THEN RETURN EXISTS (SELECT 1 FROM "ms"."messages" o WHERE (o."chat_id", o."seq") = (((authz__.v_text)::authz_gen."message__key")."chat_id", ((authz__.v_text)::authz_gen."message__key")."seq") AND ((coalesce(o."sender_id" = (SELECT authz.uid()), false)
    AND coalesce((not deleted and created_at > now() - interval '15 minutes'), false)))
    AND ((authz_int."message__check_522cac4d84"((o.*)::"ms"."messages")
    AND EXISTS (SELECT 1 FROM authz_int."chat__read" v WHERE v.id = o."chat_id"))));
