    v_ok := ($1) IN (SELECT r."id" AS id FROM "ms"."chats" r WHERE coalesce((kind = 'group'), false));
    RETURN NEXT pad || '  ' || CASE WHEN v_ok THEN 'yes  ' ELSE 'no   ' END || '{kind = ''group''}';
  END;
END $f$;

