CREATE OR REPLACE FUNCTION authz_int."message__sender__why"(p_id text, p_depth int, p_seen text[], p_asker text[])
RETURNS SETOF text LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path FROM CURRENT AS $f$
#variable_conflict use_column
<<authz__>>
DECLARE pad text := repeat('  ', p_depth); v_t record;
BEGIN
  IF $1 IN (SELECT ROW(r."chat_id"::bigint, r."seq"::bigint)::text AS id FROM "ms"."messages" r WHERE r."sender_id" = (SELECT authz.uid())) THEN
    RETURN NEXT authz__.pad || 'yes  ' || CASE WHEN $4 IS NULL THEN 'sender: sender_id is you' ELSE 'sender: sender_id is them' END || '';
    RETURN;
  END IF;
  RETURN NEXT pad || CASE WHEN $4 IS NULL THEN 'no   you do not hold ' ELSE 'no   they do not hold ' END || 'message.sender';
END $f$;

CREATE OR REPLACE FUNCTION authz_int."message__read__why"(p_id text, p_depth int, p_seen text[], p_asker text[])
RETURNS SETOF text LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path FROM CURRENT AS $f$
#variable_conflict use_column
DECLARE pad text := repeat('  ', p_depth); v_ok boolean; v_done boolean := false; v_t record;
        v_holds boolean := p_id IN (SELECT id FROM authz_int."message__read");
BEGIN
  IF p_depth > 60 THEN RETURN NEXT pad || '...'; RETURN; END IF;
  RETURN NEXT pad || 'message.read = chat.read and {seq > coalesce(ms.joined_seq(chat_id), 0)}';
  BEGIN
    v_ok := ($1) IN (SELECT ROW(r."chat_id"::bigint, r."seq"::bigint)::text AS id FROM "ms"."messages" r
  WHERE (r."chat_id", r."seq") IN (SELECT (k.k)."chat_id", (k.k)."seq" FROM (SELECT x.id::authz_gen."message__key" AS k FROM (SELECT id FROM authz_int."message__chat__read") x) k)
    AND authz_int."message__check_522cac4d84"((r.*)::"ms"."messages"));
    RETURN NEXT pad || CASE WHEN v_ok THEN 'yes  ' ELSE 'no   ' END || '(chat.read and {seq > coalesce(ms.joined_seq(chat_id), 0)})';
    v_ok := ($1) IN (SELECT id FROM authz_int."message__chat__read");
    RETURN NEXT pad || '  ' || CASE WHEN v_ok THEN 'yes  ' ELSE 'no   ' END || 'chat.read';
    FOR v_t IN SELECT tg.id::text AS id, EXISTS (SELECT 1 FROM authz_int."chat__read" v WHERE v.id = tg.id) AS ok
               FROM (SELECT r."chat_id" AS id FROM "ms"."messages" r WHERE (r."chat_id", r."seq") = ((($1)::authz_gen."message__key")."chat_id", (($1)::authz_gen."message__key")."seq") AND r."chat_id" IS NOT NULL) tg ORDER BY 2 DESC, 1 LIMIT 5 LOOP
      -- the walk stops at an object the one asking can't see: nothing about it, or above it
      IF NOT authz_int.asker_sees(p_asker, 'chat', v_t.id, false) THEN
        RETURN NEXT pad || '  ' || '       ' || 'chat is a chat you can''t see';
        CONTINUE;
      END IF;
      RETURN NEXT pad || '  ' || '  ' || CASE WHEN v_t.ok THEN 'yes  ' ELSE 'no   ' END || 'chat is chat '
                  || v_t.id || CASE WHEN v_t.ok THEN ', which has read' ELSE ', without read' END;
      IF NOT ('chat:read:' || v_t.id = ANY (p_seen)) AND ((v_t.ok AND v_ok AND v_holds) OR (NOT v_ok AND NOT v_t.ok AND p_depth < 5)) THEN
        RETURN QUERY SELECT * FROM authz_int."chat__read__why"(v_t.id::bigint, p_depth + 2 + 1, p_seen || ('chat:read:' || v_t.id), p_asker);
      END IF;
    END LOOP;
    v_ok := ($1) IN (SELECT ROW(r."chat_id"::bigint, r."seq"::bigint)::text AS id FROM "ms"."messages" r WHERE authz_int."message__check_522cac4d84"((r.*)::"ms"."messages"));
    RETURN NEXT pad || '  ' || CASE WHEN v_ok THEN 'yes  ' ELSE 'no   ' END || '{seq > coalesce(ms.joined_seq(chat_id), 0)}';
  END;
END $f$;

CREATE OR REPLACE FUNCTION authz_int."message__edit__why"(p_id text, p_depth int, p_seen text[], p_asker text[])
RETURNS SETOF text LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path FROM CURRENT AS $f$
#variable_conflict use_column
DECLARE pad text := repeat('  ', p_depth); v_ok boolean; v_done boolean := false; v_t record;
        v_holds boolean := p_id IN (SELECT id FROM authz_int."message__edit");
BEGIN
  IF p_depth > 60 THEN RETURN NEXT pad || '...'; RETURN; END IF;
  RETURN NEXT pad || 'message.edit = sender and {not deleted and created_at > now() - interval ''15 minutes''}';
  BEGIN
    v_ok := ($1) IN (SELECT ROW(r."chat_id"::bigint, r."seq"::bigint)::text AS id FROM "ms"."messages" r
  WHERE (r."chat_id", r."seq") IN (SELECT (k.k)."chat_id", (k.k)."seq" FROM (SELECT x.id::authz_gen."message__key" AS k FROM (SELECT id FROM authz_int."message__sender") x) k)
    AND coalesce((not deleted and created_at > now() - interval '15 minutes'), false));
    RETURN NEXT pad || CASE WHEN v_ok THEN 'yes  ' ELSE 'no   ' END || '(sender and {not deleted and created_at > now() - interval ''15 minutes''})';
    v_ok := ($1) IN (SELECT id FROM authz_int."message__sender");
    RETURN NEXT pad || '  ' || CASE WHEN v_ok THEN 'yes  ' ELSE 'no   ' END || 'sender';
    IF v_ok AND v_holds THEN RETURN QUERY SELECT * FROM authz_int."message__sender__why"($1, p_depth + 2, p_seen, p_asker); END IF;
    v_ok := ($1) IN (SELECT ROW(r."chat_id"::bigint, r."seq"::bigint)::text AS id FROM "ms"."messages" r WHERE coalesce((not deleted and created_at > now() - interval '15 minutes'), false));
    RETURN NEXT pad || '  ' || CASE WHEN v_ok THEN 'yes  ' ELSE 'no   ' END || '{not deleted and created_at > now() - interval ''15 minutes''}';
  END;
END $f$;

CREATE OR REPLACE FUNCTION authz_int."message__remove__why"(p_id text, p_depth int, p_seen text[], p_asker text[])
RETURNS SETOF text LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path FROM CURRENT AS $f$
#variable_conflict use_column
DECLARE pad text := repeat('  ', p_depth); v_ok boolean; v_done boolean := false; v_t record;
        v_holds boolean := p_id IN (SELECT id FROM authz_int."message__remove");
BEGIN
  IF p_depth > 60 THEN RETURN NEXT pad || '...'; RETURN; END IF;
  RETURN NEXT pad || 'message.remove = sender or chat.manage';
  BEGIN
    v_ok := ($1) IN (SELECT id FROM authz_int."message__sender");
    RETURN NEXT pad || CASE WHEN v_ok THEN 'yes  ' ELSE 'no   ' END || 'sender';
    IF v_ok AND NOT v_done THEN v_done := true; RETURN QUERY SELECT * FROM authz_int."message__sender__why"($1, p_depth + 1, p_seen, p_asker); END IF;
    v_ok := ($1) IN (SELECT id FROM authz_int."message__chat__manage");
    RETURN NEXT pad || CASE WHEN v_ok THEN 'yes  ' ELSE 'no   ' END || 'chat.manage';
    FOR v_t IN SELECT tg.id::text AS id, EXISTS (SELECT 1 FROM authz_int."chat__manage" v WHERE v.id = tg.id) AS ok
               FROM (SELECT r."chat_id" AS id FROM "ms"."messages" r WHERE (r."chat_id", r."seq") = ((($1)::authz_gen."message__key")."chat_id", (($1)::authz_gen."message__key")."seq") AND r."chat_id" IS NOT NULL) tg ORDER BY 2 DESC, 1 LIMIT 5 LOOP
      -- the walk stops at an object the one asking can't see: nothing about it, or above it
      IF NOT authz_int.asker_sees(p_asker, 'chat', v_t.id, false) THEN
        RETURN NEXT pad || '       ' || 'chat is a chat you can''t see';
        CONTINUE;
      END IF;
      RETURN NEXT pad || '  ' || CASE WHEN v_t.ok THEN 'yes  ' ELSE 'no   ' END || 'chat is chat '
                  || v_t.id || CASE WHEN v_t.ok THEN ', which has manage' ELSE ', without manage' END;
      IF NOT ('chat:manage:' || v_t.id = ANY (p_seen)) AND ((v_t.ok AND v_ok AND NOT v_done) OR (NOT v_ok AND NOT v_t.ok AND p_depth < 5)) THEN
        v_done := true; RETURN QUERY SELECT * FROM authz_int."chat__manage__why"(v_t.id::bigint, p_depth + 1 + 1, p_seen || ('chat:manage:' || v_t.id), p_asker);
      END IF;
    END LOOP;
  END;
END $f$;

-- May the signed-in user see this object (select it)? A hidden object reads as a missing one
CREATE OR REPLACE FUNCTION authz_int.visible(p_type text, p_id text) RETURNS boolean
LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path FROM CURRENT AS $f$
#variable_conflict use_column
BEGIN
  IF NOT coalesce(pg_catalog.pg_input_is_valid(p_id, (SELECT keytype FROM authz_int.types WHERE name = p_type)), false) THEN
    RETURN false;
  END IF;
  CASE p_type
    WHEN 'user' THEN
      RETURN EXISTS (SELECT 1 FROM "ms"."users" "users" WHERE "users"."id" = $2::uuid
        AND (SELECT authz_int.scope_cmd('ms.users', 'select')) AND coalesce(((SELECT authz.uid()) IS NOT NULL), false));
    WHEN 'bot' THEN
      RETURN EXISTS (SELECT 1 FROM "ms"."bots" "bots" WHERE "bots"."id" = $2::bigint
        AND (SELECT authz_int.scope_cmd('ms.bots', 'select')) AND (coalesce(((SELECT authz.uid()) IS NOT NULL), false)
    AND coalesce((active), false)));
    WHEN 'chat' THEN
      RETURN EXISTS (SELECT 1 FROM "ms"."chats" "chats" WHERE "chats"."id" = $2::bigint
        AND (SELECT authz_int.scope_cmd('ms.chats', 'select')) AND ((EXISTS (SELECT 1 FROM authz_int."chat__member" v WHERE v.id = "chats"."id")
    OR EXISTS (SELECT 1 FROM authz_int."chat__bot" v WHERE v.id = "chats"."id"))
    OR ((coalesce((kind = 'group'), false)
    AND EXISTS (SELECT 1 FROM authz_int."chat__invitee" v WHERE v.id = "chats"."id"))
    OR (coalesce((kind = 'group'), false)
    AND EXISTS (SELECT 1 FROM authz_int."chat__admin" v WHERE v.id = "chats"."id")))
    OR (coalesce("chats"."created_by" = (SELECT authz.uid()), false)
    AND coalesce((not exists (select 1 from ms.members m where m.chat_id = "chats".id)), false)
    AND coalesce((not exists (select 1 from ms.direct_pairs p where p.chat_id = "chats".id)), false))));
    WHEN 'membership' THEN
      RETURN EXISTS (SELECT 1 FROM "ms"."members" "members" WHERE ("members"."chat_id", "members"."user_id") = ((($2)::authz_gen."membership__key")."chat_id", (($2)::authz_gen."membership__key")."user_id")
        AND (SELECT authz_int.scope_cmd('ms.members', 'select')) AND EXISTS (SELECT 1 FROM authz_int."chat__read" v WHERE v.id = "members"."chat_id"));
    WHEN 'message' THEN
      RETURN EXISTS (SELECT 1 FROM "ms"."messages" "messages" WHERE ("messages"."chat_id", "messages"."seq") = ((($2)::authz_gen."message__key")."chat_id", (($2)::authz_gen."message__key")."seq")
        AND (SELECT authz_int.scope_cmd('ms.messages', 'select')) AND (authz_int."message__check_522cac4d84"(("messages".*)::"ms"."messages")
    AND EXISTS (SELECT 1 FROM authz_int."chat__read" v WHERE v.id = "messages"."chat_id")));
    WHEN 'chat_bot' THEN
      RETURN EXISTS (SELECT 1 FROM "ms"."chat_bots" "chat_bots" WHERE ("chat_bots"."chat_id", "chat_bots"."bot_id") = ((($2)::authz_gen."chat_bot__key")."chat_id", (($2)::authz_gen."chat_bot__key")."bot_id")
        AND (SELECT authz_int.scope_cmd('ms.chat_bots', 'select')) AND EXISTS (SELECT 1 FROM authz_int."chat__read" v WHERE v.id = "chat_bots"."chat_id"));
    WHEN 'block' THEN
      RETURN EXISTS (SELECT 1 FROM "ms"."blocks" "blocks" WHERE ("blocks"."blocker_id", "blocks"."blocked_id") = ((($2)::authz_gen."block__key")."blocker_id", (($2)::authz_gen."block__key")."blocked_id")
        AND (SELECT authz_int.scope_cmd('ms.blocks', 'select')) AND coalesce("blocks"."blocker_id" = (SELECT authz.uid()), false));
    ELSE RETURN false;
  END CASE;
END $f$;

-- Everyone who holds a permission on an object: SELECT * FROM authz.who('folder', 3, 'view')
-- Candidates come from the data (a superset); each is checked as that user (the permission itself, authz_int.can).
CREATE OR REPLACE FUNCTION authz.who(p_type text, p_id text, p_perm text) RETURNS SETOF text
LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path = pg_catalog, pg_temp AS $f$
#variable_conflict use_column
<<authz__>>
DECLARE v_me text := coalesce(current_setting('authz.user_id', true), ''); v_c text;
        v_pt text := coalesce(current_setting('authz.principal_type', true), '');
        v_scopes text := coalesce(current_setting('authz.scopes', true), ''); v_bigint bigint; v_text text; v_uuid uuid;
BEGIN
  IF NOT authz_int.may_inspect(p_type, p_id) OR NOT authz_int.scope_perm(p_type, p_perm) THEN
    RAISE EXCEPTION 'you cannot see who has access to % %', p_type, p_id USING ERRCODE = 'insufficient_privilege', HINT = 'rowstile help AZ705';
  END IF;
  -- (the caller's settings are put back below; an error needs nothing put back: Postgres undoes these settings with
  -- the transaction, or the savepoint the error is caught at, as for explain, check_invariants and the logins)
  PERFORM set_config('authz.scopes', '', true);   -- each candidate is checked with full rights
  PERFORM set_config('authz.principal_type', '', true);   -- candidates are users
  <<asking>> BEGIN
  CASE p_type
    WHEN 'user' THEN
      IF NOT pg_catalog.pg_input_is_valid(p_id, 'uuid') THEN EXIT asking; END IF;
      v_uuid := p_id::uuid;
      CASE p_perm
        WHEN 'edit' THEN
          FOR v_c IN SELECT DISTINCT c.id::text FROM authz_int."user__edit__who"(authz__.v_uuid) c(id) WHERE EXISTS (SELECT 1 FROM "ms"."users" u WHERE u."id" = c.id) LOOP
            PERFORM set_config('authz.user_id', v_c, true);
            PERFORM authz_int.sign();
            IF authz_int.can(p_type, p_id, p_perm) THEN RETURN NEXT v_c; END IF;
          END LOOP;
        WHEN 'see_phone' THEN
          FOR v_c IN SELECT DISTINCT c.id::text FROM authz_int."user__see_phone__who"(authz__.v_uuid) c(id) WHERE EXISTS (SELECT 1 FROM "ms"."users" u WHERE u."id" = c.id) LOOP
            PERFORM set_config('authz.user_id', v_c, true);
            PERFORM authz_int.sign();
            IF authz_int.can(p_type, p_id, p_perm) THEN RETURN NEXT v_c; END IF;
          END LOOP;
        ELSE RAISE EXCEPTION 'no permission %.% in the policy', p_type, p_perm USING HINT = 'rowstile help AZ707';
      END CASE;
    WHEN 'bot' THEN
      IF NOT pg_catalog.pg_input_is_valid(p_id, 'bigint') THEN EXIT asking; END IF;
      v_bigint := p_id::bigint;
      CASE p_perm
        WHEN 'manage' THEN
          FOR v_c IN SELECT DISTINCT c.id::text FROM authz_int."bot__manage__who"(authz__.v_bigint) c(id) WHERE EXISTS (SELECT 1 FROM "ms"."users" u WHERE u."id" = c.id) LOOP
            PERFORM set_config('authz.user_id', v_c, true);
            PERFORM authz_int.sign();
            IF authz_int.can(p_type, p_id, p_perm) THEN RETURN NEXT v_c; END IF;
          END LOOP;
        WHEN 'manage_keys' THEN
          FOR v_c IN SELECT DISTINCT c.id::text FROM authz_int."bot__manage_keys__who"(authz__.v_bigint) c(id) WHERE EXISTS (SELECT 1 FROM "ms"."users" u WHERE u."id" = c.id) LOOP
            PERFORM set_config('authz.user_id', v_c, true);
            PERFORM authz_int.sign();
            IF authz_int.can(p_type, p_id, p_perm) THEN RETURN NEXT v_c; END IF;
          END LOOP;
        ELSE RAISE EXCEPTION 'no permission %.% in the policy', p_type, p_perm USING HINT = 'rowstile help AZ707';
      END CASE;
    WHEN 'chat' THEN
      IF NOT pg_catalog.pg_input_is_valid(p_id, 'bigint') THEN EXIT asking; END IF;
      v_bigint := p_id::bigint;
      CASE p_perm
        WHEN 'read' THEN
          FOR v_c IN SELECT DISTINCT c.id::text FROM authz_int."chat__read__who"(authz__.v_bigint) c(id) WHERE EXISTS (SELECT 1 FROM "ms"."users" u WHERE u."id" = c.id) LOOP
            PERFORM set_config('authz.user_id', v_c, true);
            PERFORM authz_int.sign();
            IF authz_int.can(p_type, p_id, p_perm) THEN RETURN NEXT v_c; END IF;
          END LOOP;
        WHEN 'post' THEN
          FOR v_c IN SELECT DISTINCT c.id::text FROM authz_int."chat__post__who"(authz__.v_bigint) c(id) WHERE EXISTS (SELECT 1 FROM "ms"."users" u WHERE u."id" = c.id) LOOP
            PERFORM set_config('authz.user_id', v_c, true);
            PERFORM authz_int.sign();
            IF authz_int.can(p_type, p_id, p_perm) THEN RETURN NEXT v_c; END IF;
          END LOOP;
        WHEN 'manage' THEN
          FOR v_c IN SELECT DISTINCT c.id::text FROM authz_int."chat__manage__who"(authz__.v_bigint) c(id) WHERE EXISTS (SELECT 1 FROM "ms"."users" u WHERE u."id" = c.id) LOOP
            PERFORM set_config('authz.user_id', v_c, true);
            PERFORM authz_int.sign();
            IF authz_int.can(p_type, p_id, p_perm) THEN RETURN NEXT v_c; END IF;
          END LOOP;
        WHEN 'invite' THEN
          FOR v_c IN SELECT DISTINCT c.id::text FROM authz_int."chat__invite__who"(authz__.v_bigint) c(id) WHERE EXISTS (SELECT 1 FROM "ms"."users" u WHERE u."id" = c.id) LOOP
            PERFORM set_config('authz.user_id', v_c, true);
            PERFORM authz_int.sign();
            IF authz_int.can(p_type, p_id, p_perm) THEN RETURN NEXT v_c; END IF;
          END LOOP;
        WHEN 'join' THEN
          FOR v_c IN SELECT DISTINCT c.id::text FROM authz_int."chat__join__who"(authz__.v_bigint) c(id) WHERE EXISTS (SELECT 1 FROM "ms"."users" u WHERE u."id" = c.id) LOOP
            PERFORM set_config('authz.user_id', v_c, true);
            PERFORM authz_int.sign();
            IF authz_int.can(p_type, p_id, p_perm) THEN RETURN NEXT v_c; END IF;
          END LOOP;
        WHEN 'setup' THEN
          FOR v_c IN SELECT DISTINCT c.id::text FROM authz_int."chat__setup__who"(authz__.v_bigint) c(id) WHERE EXISTS (SELECT 1 FROM "ms"."users" u WHERE u."id" = c.id) LOOP
            PERFORM set_config('authz.user_id', v_c, true);
            PERFORM authz_int.sign();
            IF authz_int.can(p_type, p_id, p_perm) THEN RETURN NEXT v_c; END IF;
          END LOOP;
        WHEN 'add_members' THEN
          FOR v_c IN SELECT DISTINCT c.id::text FROM authz_int."chat__add_members__who"(authz__.v_bigint) c(id) WHERE EXISTS (SELECT 1 FROM "ms"."users" u WHERE u."id" = c.id) LOOP
            PERFORM set_config('authz.user_id', v_c, true);
            PERFORM authz_int.sign();
            IF authz_int.can(p_type, p_id, p_perm) THEN RETURN NEXT v_c; END IF;
          END LOOP;
        ELSE RAISE EXCEPTION 'no permission %.% in the policy', p_type, p_perm USING HINT = 'rowstile help AZ707';
      END CASE;
    WHEN 'membership' THEN
      IF NOT pg_catalog.pg_input_is_valid(p_id, 'authz_gen."membership__key"') THEN EXIT asking; END IF;
      v_text := p_id::authz_gen."membership__key"::text;
      RAISE EXCEPTION 'no permission %.% in the policy', p_type, p_perm USING HINT = 'rowstile help AZ707';
    WHEN 'message' THEN
      IF NOT pg_catalog.pg_input_is_valid(p_id, 'authz_gen."message__key"') THEN EXIT asking; END IF;
      v_text := p_id::authz_gen."message__key"::text;
      CASE p_perm
        WHEN 'read' THEN
          FOR v_c IN SELECT DISTINCT c.id::text FROM authz_int."message__read__who"(authz__.v_text) c(id) WHERE EXISTS (SELECT 1 FROM "ms"."users" u WHERE u."id" = c.id) LOOP
            PERFORM set_config('authz.user_id', v_c, true);
            PERFORM authz_int.sign();
            IF authz_int.can(p_type, p_id, p_perm) THEN RETURN NEXT v_c; END IF;
          END LOOP;
        WHEN 'edit' THEN
          FOR v_c IN SELECT DISTINCT c.id::text FROM authz_int."message__edit__who"(authz__.v_text) c(id) WHERE EXISTS (SELECT 1 FROM "ms"."users" u WHERE u."id" = c.id) LOOP
            PERFORM set_config('authz.user_id', v_c, true);
            PERFORM authz_int.sign();
            IF authz_int.can(p_type, p_id, p_perm) THEN RETURN NEXT v_c; END IF;
          END LOOP;
        WHEN 'remove' THEN
          FOR v_c IN SELECT DISTINCT c.id::text FROM authz_int."message__remove__who"(authz__.v_text) c(id) WHERE EXISTS (SELECT 1 FROM "ms"."users" u WHERE u."id" = c.id) LOOP
            PERFORM set_config('authz.user_id', v_c, true);
            PERFORM authz_int.sign();
            IF authz_int.can(p_type, p_id, p_perm) THEN RETURN NEXT v_c; END IF;
          END LOOP;
        ELSE RAISE EXCEPTION 'no permission %.% in the policy', p_type, p_perm USING HINT = 'rowstile help AZ707';
      END CASE;
    WHEN 'chat_bot' THEN
      IF NOT pg_catalog.pg_input_is_valid(p_id, 'authz_gen."chat_bot__key"') THEN EXIT asking; END IF;
      v_text := p_id::authz_gen."chat_bot__key"::text;
      RAISE EXCEPTION 'no permission %.% in the policy', p_type, p_perm USING HINT = 'rowstile help AZ707';
    WHEN 'block' THEN
      IF NOT pg_catalog.pg_input_is_valid(p_id, 'authz_gen."block__key"') THEN EXIT asking; END IF;
      v_text := p_id::authz_gen."block__key"::text;
      RAISE EXCEPTION 'no permission %.% in the policy', p_type, p_perm USING HINT = 'rowstile help AZ707';
    ELSE
      RAISE EXCEPTION 'no type % in the policy', p_type USING HINT = 'rowstile help AZ707';
  END CASE;
  END asking;
  PERFORM set_config('authz.user_id', v_me, true);
  PERFORM set_config('authz.principal_type', v_pt, true);
  PERFORM set_config('authz.scopes', v_scopes, true);
  PERFORM authz_int.sign();
END $f$;

-- Invariants: checked as everyone who can sign in (named as the audit trail names them: '42', 'user:a:b',
-- 'service:3') and as nobody; returns the violations
CREATE OR REPLACE FUNCTION authz.check_invariants() RETURNS TABLE (invariant text, user_id text, object_ids text[])
LANGUAGE plpgsql SECURITY DEFINER SET search_path = pg_catalog, pg_temp AS $f$
#variable_conflict use_column
DECLARE v_me text := coalesce(current_setting('authz.user_id', true), ''); v_pt text := coalesce(current_setting('authz.principal_type', true), '');
        v_scopes text := coalesce(current_setting('authz.scopes', true), ''); v_p text; v_u text; v_ids text[];
BEGIN
  PERFORM set_config('authz.scopes', '', true);
  FOR v_p, v_u IN SELECT '', '' UNION ALL SELECT '', x."id"::text FROM "ms"."users" x UNION ALL SELECT 'bot', x."id"::text FROM "ms"."bots" x LOOP
    PERFORM set_config('authz.principal_type', v_p, true);
    PERFORM set_config('authz.user_id', v_u, true);
    PERFORM authz_int.sign();
    NULL;
  END LOOP;
  PERFORM set_config('authz.user_id', v_me, true);
  PERFORM set_config('authz.principal_type', v_pt, true);
  PERFORM set_config('authz.scopes', v_scopes, true);
  PERFORM authz_int.sign();
END $f$;

-- Replace a group's members with the list your identity provider sends (administrators, sync jobs):
-- SELECT * FROM authz.sync_members('team', '10', 'member', ARRAY['1', '2'])
CREATE OR REPLACE FUNCTION authz.sync_members(p_type text, p_id text, p_relation text, p_members text[],
  OUT added int, OUT removed int)
LANGUAGE plpgsql SECURITY DEFINER SET search_path = pg_catalog, pg_temp AS $f$
#variable_conflict use_column
BEGIN
  -- NULL is no list: it would remove every member (a sync job's failed fetch, a missing field)
  IF p_members IS NULL OR EXISTS (SELECT 1 FROM unnest(p_members) x WHERE x IS NULL) THEN
    RAISE EXCEPTION 'say who the members are: a list of ids with no NULL in it (an empty list for none)'
      USING ERRCODE = 'invalid_parameter_value', HINT = 'rowstile help AZ710';
  END IF;
  CASE p_type || '.' || p_relation
    WHEN 'user.has_blocked' THEN
      WITH want AS (SELECT DISTINCT x::uuid AS m FROM unnest($4) x),
      del AS (DELETE FROM "ms"."blocks" s WHERE s."blocker_id" = $2::uuid AND s."blocked_id" NOT IN (SELECT m FROM want) RETURNING 1),
      ins AS (INSERT INTO "ms"."blocks" ("blocker_id", "blocked_id") SELECT $2::uuid, w.m FROM want w
              WHERE NOT EXISTS (SELECT 1 FROM "ms"."blocks" s WHERE s."blocker_id" = $2::uuid AND s."blocked_id" = w.m) RETURNING 1)
      SELECT (SELECT count(*) FROM ins)::int, (SELECT count(*) FROM del)::int INTO added, removed;
    WHEN 'chat.member' THEN
      WITH want AS (SELECT DISTINCT x::uuid AS m FROM unnest($4) x),
      del AS (DELETE FROM "ms"."members" s WHERE s."chat_id" = $2::bigint AND s."user_id" NOT IN (SELECT m FROM want) RETURNING 1),
      ins AS (INSERT INTO "ms"."members" ("chat_id", "user_id") SELECT $2::bigint, w.m FROM want w
              WHERE NOT EXISTS (SELECT 1 FROM "ms"."members" s WHERE s."chat_id" = $2::bigint AND s."user_id" = w.m) RETURNING 1)
      SELECT (SELECT count(*) FROM ins)::int, (SELECT count(*) FROM del)::int INTO added, removed;
    WHEN 'chat.blocked' THEN
      WITH want AS (SELECT DISTINCT x::uuid AS m FROM unnest($4) x),
      del AS (DELETE FROM "ms"."direct_blocks" s WHERE s."chat_id" = $2::bigint AND s."user_id" NOT IN (SELECT m FROM want) RETURNING 1),
      ins AS (INSERT INTO "ms"."direct_blocks" ("chat_id", "user_id") SELECT $2::bigint, w.m FROM want w
              WHERE NOT EXISTS (SELECT 1 FROM "ms"."direct_blocks" s WHERE s."chat_id" = $2::bigint AND s."user_id" = w.m) RETURNING 1)
      SELECT (SELECT count(*) FROM ins)::int, (SELECT count(*) FROM del)::int INTO added, removed;
    ELSE RAISE EXCEPTION '%.% has no single table of members to sync (it needs one source: table(group -> user), without where)',
      p_type, p_relation USING HINT = 'rowstile help AZ707';
  END CASE;
  PERFORM authz_int.audit('sync_members', p_type, authz_int.canon(p_type, p_id), p_relation, 'user', NULL, NULL,
                          jsonb_build_object('added', added, 'removed', removed, 'members', p_members));
END $f$;

-- the API keys of user rows that are gone, or whose id changed, are deleted (authz_int.keys_gone)
CREATE OR REPLACE FUNCTION authz_int."user__keys_gone"() RETURNS trigger
LANGUAGE plpgsql SECURITY DEFINER SET search_path FROM CURRENT AS $f$
#variable_conflict use_column
BEGIN
  IF TG_OP = 'TRUNCATE' THEN
    IF NOT EXISTS (SELECT 1 FROM "ms"."users") THEN   -- the table is empty, and so are those under it
      PERFORM authz_int.keys_gone('user', NULL);
    ELSE   -- TRUNCATE ONLY, or of a table under it: the rows still there keep their keys
      PERFORM authz_int.keys_gone('user', ARRAY(SELECT k.user_id FROM authz.api_keys k WHERE k.principal_type = 'user'
                                                AND NOT EXISTS (SELECT 1 FROM "ms"."users" x WHERE x."id"::text = k.user_id)));
    END IF;
  ELSIF TG_OP = 'UPDATE' THEN   -- on a partitioned table (the last trigger below): the ids the update left no row with
    PERFORM authz_int.keys_gone('user', ARRAY(SELECT o."id"::text FROM old_rows o EXCEPT SELECT n."id"::text FROM new_rows n));
  ELSE
    PERFORM authz_int.keys_gone('user', ARRAY(SELECT o."id"::text FROM old_rows o));
  END IF;
  RETURN NULL;
END $f$;

-- the API keys of bot rows that are gone, or whose id changed, are deleted (authz_int.keys_gone)
CREATE OR REPLACE FUNCTION authz_int."bot__keys_gone"() RETURNS trigger
LANGUAGE plpgsql SECURITY DEFINER SET search_path FROM CURRENT AS $f$
#variable_conflict use_column
BEGIN
  IF TG_OP = 'TRUNCATE' THEN
    IF NOT EXISTS (SELECT 1 FROM "ms"."bots") THEN   -- the table is empty, and so are those under it
      PERFORM authz_int.keys_gone('bot', NULL);
    ELSE   -- TRUNCATE ONLY, or of a table under it: the rows still there keep their keys
      PERFORM authz_int.keys_gone('bot', ARRAY(SELECT k.user_id FROM authz.api_keys k WHERE k.principal_type = 'bot'
                                                AND NOT EXISTS (SELECT 1 FROM "ms"."bots" x WHERE x."id"::text = k.user_id)));
    END IF;
  ELSIF TG_OP = 'UPDATE' THEN   -- on a partitioned table (the last trigger below): the ids the update left no row with
    PERFORM authz_int.keys_gone('bot', ARRAY(SELECT o."id"::text FROM old_rows o EXCEPT SELECT n."id"::text FROM new_rows n));
  ELSE
    PERFORM authz_int.keys_gone('bot', ARRAY(SELECT o."id"::text FROM old_rows o));
  END IF;
  RETURN NULL;
END $f$;

-- The partitions of each table with rules and the tables that inherit from one: row-level security on, with
-- no policies of their own, so they are read and written through it only (read directly, they would skip its rules
-- and triggers). Every apply and every migration: one made or attached since is closed too (it alone is locked,
-- as CHILD_TRIGGERS locks only one that lacks the triggers)
DO $rls$
DECLARE c regclass;
BEGIN
  FOR c IN WITH RECURSIVE d(oid) AS (
             SELECT i.inhrelid FROM pg_catalog.pg_inherits i
             WHERE i.inhparent = ANY (SELECT to_regclass(x)::oid FROM unnest(ARRAY['"ms"."blocks"', '"ms"."bots"', '"ms"."chat_bots"', '"ms"."chats"', '"ms"."members"', '"ms"."messages"', '"ms"."users"']::text[]) x)
             UNION SELECT i.inhrelid FROM pg_catalog.pg_inherits i JOIN d ON i.inhparent = d.oid)
           SELECT d.oid::regclass FROM d JOIN pg_catalog.pg_class k ON k.oid = d.oid WHERE NOT k.relrowsecurity LOOP
    EXECUTE format('ALTER TABLE %s ENABLE ROW LEVEL SECURITY', c);
  END LOOP;
END $rls$;

-- The partitions of a table rowstile watches and the tables that inherit from it: the triggers made above, on
-- each, for the rows stored there and the statements on it
DO $ch$
DECLARE r record;
BEGIN
  FOR r IN SELECT * FROM authz_int.child_triggers() LOOP
    EXECUTE r.stmt;
    EXECUTE pg_catalog.format('COMMENT ON TRIGGER %I ON %s IS %L', r.name, r.child, 'rowstile: the trigger of the table above, for the rows stored here');
  END LOOP;
END $ch$;

-- Privileges the policy doesn't give on rowstile's schemas and what is in them are taken back
DO $r$
DECLARE g record; v_taken int := 0;
BEGIN
  FOR g IN SELECT n.nspname::text AS object, gw.who, a.privilege_type AS privilege,
       format('REVOKE %s ON SCHEMA %I FROM %s CASCADE', a.privilege_type, n.nspname, gw.who) AS stmt
  FROM pg_namespace n, aclexplode(n.nspacl) a, LATERAL (SELECT CASE a.grantee WHEN 0 THEN 'PUBLIC' ELSE a.grantee::regrole::text END AS who) gw
  WHERE n.nspname IN ('authz', 'authz_gen', 'authz_int') AND a.grantee <> n.nspowner
    AND NOT (a.grantee = '"ms_app"'::regrole AND n.nspname <> 'authz_int' AND a.privilege_type = 'USAGE')
UNION ALL
SELECT c.oid::regclass::text, gw.who, a.privilege_type,
       format('REVOKE %s ON %s %s FROM %s CASCADE', a.privilege_type, CASE c.relkind WHEN 'S' THEN 'SEQUENCE' ELSE 'TABLE' END,
              c.oid::regclass, gw.who)
  FROM pg_class c, aclexplode(c.relacl) a, LATERAL (SELECT CASE a.grantee WHEN 0 THEN 'PUBLIC' ELSE a.grantee::regrole::text END AS who) gw
  WHERE c.relnamespace IN (SELECT oid FROM pg_namespace WHERE nspname IN ('authz', 'authz_gen', 'authz_int')) AND a.grantee <> c.relowner
    AND NOT (a.grantee = '"ms_app"'::regrole AND a.privilege_type = 'SELECT'
             AND c.relnamespace::regnamespace::text || '."' || replace(c.relname, '"', '""') || '"' = ANY (ARRAY['authz_gen."policy_lines"', 'authz_int."bot__manage"', 'authz_int."chat__add_members"', 'authz_int."chat__admin"', 'authz_int."chat__bot"', 'authz_int."chat__invitee"', 'authz_int."chat__join"', 'authz_int."chat__manage"', 'authz_int."chat__member"', 'authz_int."chat__owner"', 'authz_int."chat__post"', 'authz_int."chat__read"', 'authz_int."chat__setup"', 'authz_int."user__has_blocked"']::text[]))
UNION ALL
SELECT format('%s (%I)', c.oid::regclass, att.attname), gw.who, a.privilege_type,
       format('REVOKE %s (%I) ON %s FROM %s CASCADE', a.privilege_type, att.attname, c.oid::regclass, gw.who)
  FROM pg_class c JOIN pg_attribute att ON att.attrelid = c.oid, aclexplode(att.attacl) a, LATERAL (SELECT CASE a.grantee WHEN 0 THEN 'PUBLIC' ELSE a.grantee::regrole::text END AS who) gw
  WHERE c.relnamespace IN (SELECT oid FROM pg_namespace WHERE nspname IN ('authz', 'authz_gen', 'authz_int')) AND att.attacl IS NOT NULL
UNION ALL
SELECT p.oid::regprocedure::text, gw.who, a.privilege_type,
       format('REVOKE %s ON ROUTINE %s FROM %s CASCADE', a.privilege_type, p.oid::regprocedure, gw.who)
  FROM pg_proc p, aclexplode(p.proacl) a, LATERAL (SELECT CASE a.grantee WHEN 0 THEN 'PUBLIC' ELSE a.grantee::regrole::text END AS who) gw
  WHERE p.pronamespace IN (SELECT oid FROM pg_namespace WHERE nspname IN ('authz', 'authz_gen', 'authz_int')) AND a.grantee <> p.proowner
    AND NOT (p.pronamespace = 'authz_int'::regnamespace AND a.grantee IN (0, '"ms_app"'::regrole))
    AND NOT (p.pronamespace = 'authz_gen'::regnamespace AND a.grantee = '"ms_app"'::regrole
             AND '"' || replace(p.proname, '"', '""') || '"' = ANY (ARRAY['"ms.blocks:delete:items"', '"ms.blocks:delete:why"', '"ms.blocks:insert:items"', '"ms.blocks:insert:refuse"', '"ms.blocks:insert:why"', '"ms.blocks:rules:explain"', '"ms.bots:column id, owner_id:items"', '"ms.bots:column id, owner_id:why"', '"ms.bots:delete:items"', '"ms.bots:delete:why"', '"ms.bots:insert:items"', '"ms.bots:insert:refuse"', '"ms.bots:insert:why"', '"ms.bots:rules:explain"', '"ms.bots:update:items"', '"ms.bots:update:refuse"', '"ms.bots:update:why"', '"ms.chat_bots:delete:items"', '"ms.chat_bots:delete:why"', '"ms.chat_bots:insert:items"', '"ms.chat_bots:insert:refuse"', '"ms.chat_bots:insert:why"', '"ms.chat_bots:rules:explain"', '"ms.chats:column kind, created_by, created_at, last_seq:items"', '"ms.chats:column kind, created_by, created_at, last_seq:why"', '"ms.chats:delete:items"', '"ms.chats:delete:why"', '"ms.chats:insert:items"', '"ms.chats:insert:refuse"', '"ms.chats:insert:why"', '"ms.chats:rules:explain"', '"ms.chats:update:items"', '"ms.chats:update:refuse"', '"ms.chats:update:why"', '"ms.members:column chat_id, user_id, joined_at, joined_seq:items"', '"ms.members:column chat_id, user_id, joined_at, joined_seq:why"', '"ms.members:column last_read_seq after:items"', '"ms.members:column last_read_seq after:why"', '"ms.members:column last_read_seq:items"', '"ms.members:column last_read_seq:why"', '"ms.members:column role after:items"', '"ms.members:column role after:why"', '"ms.members:column role:items"', '"ms.members:column role:why"', '"ms.members:delete:items"', '"ms.members:delete:why"', '"ms.members:insert:items"', '"ms.members:insert:refuse"', '"ms.members:insert:why"', '"ms.members:rules:explain"', '"ms.members:update:items"', '"ms.members:update:refuse"', '"ms.members:update:why"', '"ms.messages:column body after:items"', '"ms.messages:column body after:why"', '"ms.messages:column chat_id, seq, sender_id, bot_id, cr_cb6d8c70"', '"ms.messages:column chat_id, se